const STATIC_SW = "/* WatchFilms P2P Service Worker: intercepts video range requests and streams from WebRTC */\n\"use strict\";\n\nself.addEventListener(\"install\", (event) =\u003e {\n  self.skipWaiting();\n});\n\nself.addEventListener(\"activate\", (event) =\u003e {\n  event.waitUntil(self.clients.claim());\n});\n\nlet reqCounter = 0;\nconst pending = new Map();\n\nself.addEventListener(\"message\", (event) =\u003e {\n  const d = event.data;\n  if (!d || !d.reqId) return;\n  const p = pending.get(d.reqId);\n  if (!p) return;\n\n  if (d.type === \"meta\") {\n    if (p.onMeta) p.onMeta(d);\n  } else if (d.type === \"chunk\") {\n    if (p.onChunk) p.onChunk(d.chunk);\n  } else if (d.type === \"done\") {\n    if (p.onDone) p.onDone();\n    pending.delete(d.reqId);\n  } else if (d.type === \"error\") {\n    if (p.onError) p.onError(d.error);\n    pending.delete(d.reqId);\n  } else if (d.type === \"subs\") {\n    if (p.onSubs) p.onSubs(d);\n    pending.delete(d.reqId);\n  }\n});\n\nself.addEventListener(\"fetch\", (event) =\u003e {\n  const url = new URL(event.request.url);\n  if (url.pathname.endsWith(\"/p2p/video\")) {\n    event.respondWith(handleP2PVideo(event.request, event.clientId));\n  } else if (url.pathname.includes(\"/p2p/subs/\")) {\n    event.respondWith(handleP2PSubs(event.request, event.clientId));\n  }\n});\n\nasync function getClient(clientId) {\n  if (clientId) {\n    const c = await self.clients.get(clientId);\n    if (c) return c;\n  }\n  const all = await self.clients.matchAll({ type: \"window\" });\n  return all[0] || null;\n}\n\nasync function handleP2PVideo(request, clientId) {\n  const client = await getClient(clientId);\n  if (!client) {\n    return new Response(\"WatchFilms client window not found\", { status: 503 });\n  }\n\n  const rangeHeader = request.headers.get(\"range\");\n  let start = 0, end = -1;\n  if (rangeHeader) {\n    const m = /bytes=(\\d+)-(\\d*)/.exec(rangeHeader);\n    if (m) {\n      start = parseInt(m[1], 10);\n      if (m[2]) end = parseInt(m[2], 10);\n    }\n  }\n\n  const reqId = ++reqCounter;\n\n  return new Promise((resolve) =\u003e {\n    let controllerRef = null;\n\n    pending.set(reqId, {\n      onMeta: (meta) =\u003e {\n        const stream = new ReadableStream({\n          start(controller) {\n            controllerRef = controller;\n          },\n          cancel() {\n            client.postMessage({ type: \"p2p_cancel\", reqId });\n            pending.delete(reqId);\n          },\n        });\n\n        const status = meta.status || 206;\n        const headers = new Headers();\n        headers.set(\"Content-Type\", meta.mime || \"video/mp4\");\n        headers.set(\"Accept-Ranges\", \"bytes\");\n        headers.set(\"Content-Range\", `bytes ${meta.start}-${meta.end}/${meta.total}`);\n        headers.set(\"Content-Length\", String(meta.length));\n        headers.set(\"Cache-Control\", \"no-cache\");\n\n        resolve(new Response(stream, {\n          status: status,\n          statusText: \"Partial Content\",\n          headers: headers,\n        }));\n      },\n      onChunk: (chunk) =\u003e {\n        if (controllerRef) {\n          controllerRef.enqueue(new Uint8Array(chunk));\n        }\n      },\n      onDone: () =\u003e {\n        if (controllerRef) {\n          try { controllerRef.close(); } catch (_) {}\n        }\n      },\n      onError: (err) =\u003e {\n        if (controllerRef) {\n          try { controllerRef.error(new Error(err)); } catch (_) {}\n        }\n        resolve(new Response(err || \"Media error\", { status: 500 }));\n      },\n    });\n\n    client.postMessage({\n      type: \"p2p_request_range\",\n      reqId: reqId,\n      start: start,\n      end: end,\n    });\n  });\n}\n\nasync function handleP2PSubs(request, clientId) {\n  const client = await getClient(clientId);\n  if (!client) return new Response(\"Client not found\", { status: 503 });\n\n  const url = new URL(request.url);\n  const parts = url.pathname.split(\"/\");\n  const nStr = parts[parts.length - 1].replace(\".vtt\", \"\");\n  const n = parseInt(nStr, 10) || 0;\n  const reqId = ++reqCounter;\n\n  return new Promise((resolve) =\u003e {\n    pending.set(reqId, {\n      onSubs: (res) =\u003e {\n        resolve(new Response(res.content || \"\", {\n          status: res.status || 200,\n          headers: { \"Content-Type\": \"text/vtt; charset=utf-8\" },\n        }));\n      },\n      onError: (err) =\u003e {\n        resolve(new Response(err || \"Subtitle error\", { status: 404 }));\n      },\n    });\n\n    client.postMessage({\n      type: \"p2p_request_subs\",\n      reqId: reqId,\n      n: n,\n    });\n  });\n}\n";

function reply(statusCode, headers, body, isBase64 = false) {
  return {
    statusCode,
    headers: { ...CORS, ...headers },
    body: typeof body === 'object' ? JSON.stringify(body) : body,
    isBase64Encoded: isBase64,
  };
}

function parseBody(event) {
  if (!event.body) return {};
  try {
    const raw = event.isBase64Encoded
      ? Buffer.from(event.body, 'base64').toString('utf8')
      : event.body;
    return typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch (_) {
    return {};
  }
}

async function persistStore(room, action, sdp) {
  try {
    const b64 = Buffer.from(sdp, 'utf8').toString('base64');
    await fetch('https://ntfy.sh/wf-' + encodeURIComponent(room) + '-' + action, {
      method: 'POST',
      body: b64,
      headers: { 'Title': action },
      signal: AbortSignal.timeout ? AbortSignal.timeout(2000) : undefined,
    });
  } catch (_) {}
}

async function persistGet(room, action) {
  try {
    const res = await fetch('https://ntfy.sh/wf-' + encodeURIComponent(room) + '-' + action + '/raw?poll=1&since=10m', {
      signal: AbortSignal.timeout ? AbortSignal.timeout(2000) : undefined,
    });
    if (res.ok) {
      const text = await res.text();
      if (text && text.trim()) {
        const lines = text.trim().split('\n');
        const latest = lines[lines.length - 1].trim();
        try {
          const decoded = Buffer.from(latest, 'base64').toString('utf8');
          if (decoded.includes('v=')) return decoded;
        } catch (_) {}
        if (latest.includes('v=')) return latest;
      }
    }
  } catch (_) {}
  return null;
}

exports.handler = async function (event, context) {
  const method = (event.httpMethod || 'GET').toUpperCase();
  const urlPath = event.url || event.path || '/';
  const params = event.queryStringParameters || {};

  if (method === 'OPTIONS') {
    return reply(204, {}, '');
  }

  // --- API Сигнального сервера P2P ---
  // Обрабатываем POST запросы или GET с параметром action
  const isSignal = urlPath.includes('/api/signal') || method === 'POST' || (params && params.action);
  if (isSignal) {
    if (method === 'POST') {
      const data = parseBody(event);
      const action = data.action;
      const room = data.room;
      const sdp = data.sdp;

      if (!room || !action || !sdp) {
        return reply(400, { 'Content-Type': 'application/json' }, { error: 'room, action, and sdp required' });
      }

      let r = rooms.get(room);
      if (!r) {
        r = { createdAt: Date.now() };
        rooms.set(room, r);
      }
      r[action] = sdp;
      r.updatedAt = Date.now();

      await persistStore(room, action, sdp);

      return reply(200, { 'Content-Type': 'application/json' }, { ok: true, action, room });
    }

    if (method === 'GET') {
      const room = params.room;
      const action = params.action; // "offer" или "answer"
      if (!room || !action) {
        return reply(400, { 'Content-Type': 'application/json' }, { error: 'room and action required' });
      }

      let r = rooms.get(room);
      let sdp = r && r[action];
      if (!sdp) {
        sdp = await persistGet(room, action);
        if (sdp) {
          if (!r) {
            r = { createdAt: Date.now() };
            rooms.set(room, r);
          }
          r[action] = sdp;
        }
      }

      if (!sdp) {
        return reply(404, { 'Content-Type': 'application/json' }, { error: 'not ready' });
      }

      return reply(200, { 'Content-Type': 'application/json' }, {
        action,
        room,
        sdp,
      });
    }
  }

  // --- Статические файлы ---
  if (urlPath.endsWith('/sw.js') || params.file === 'sw.js' || params.sw === '1') {
    return reply(200, {
      'Content-Type': 'application/javascript; charset=utf-8',
      'Service-Worker-Allowed': '/',
      'Cache-Control': 'public, max-age=3600',
    }, STATIC_SW);
  }

  if (urlPath.endsWith('/style.css') || params.file === 'style.css') {
    return reply(200, {
      'Content-Type': 'text/css; charset=utf-8',
      'Cache-Control': 'public, max-age=3600',
    }, STATIC_CSS);
  }

  if (urlPath.endsWith('/app.js') || params.file === 'app.js') {
    return reply(200, {
      'Content-Type': 'application/javascript; charset=utf-8',
      'Cache-Control': 'public, max-age=3600',
    }, STATIC_JS);
  }

  // Главная страница просмотра (index.html со встроенным CSS и JS)
  return reply(200, {
    'Content-Type': 'text/html; charset=utf-8',
    'Cache-Control': 'no-cache',
    'Content-Security-Policy': "default-src * 'unsafe-inline' 'unsafe-eval' data: blob:; worker-src * blob: data: 'self'; child-src * blob: data:;",
  }, STATIC_HTML);
};
